import * as github from '@actions/github';
import { matcherRegexAny } from './utils';
export default async function match(client, config) {
    const number = github.context.payload.pull_request?.number;
    if (!number) {
        return [];
    }
    const matchers = config.labels.filter((value) => {
        return value.matcher?.commits;
    });
    if (!matchers.length) {
        return [];
    }
    const responses = await client.paginate(client.rest.pulls.listCommits.endpoint.merge({
        owner: github.context.repo.owner,
        repo: github.context.repo.repo,
        pull_number: number,
    }));
    const messages = responses.map((c) => c.commit.message);
    return matchers
        .filter((value) => {
        return matcherRegexAny(value.matcher.commits, messages);
    })
        .map((value) => value.label);
}
